export const MONUMENTS = JSON.parse("[{\"id\":\"n5724836272\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-2778.6,\"z\":-364.3,\"subject\":\"Q126306\",\"inscription\":\"На этой площади (б. Сенатской) 14 (26) декабря 1825 года произошло восстание декабристов, первое в России вооруженное выступление против самодержавия\"},{\"id\":\"n9927579884\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Общество ремесленного и земледельческого труда\",\"x\":-2867.5,\"z\":-297.2,\"inscription\":\"В этом доме в 1880 году Петербургской еврейской общиной основано Общество ремесленного и земледельческого труда среди евреев в России, внесшее значительный вклад в профессиональное обучение российской молодежи\"},{\"id\":\"n2387911123\",\"kind\":\"memorial\",\"sub\":\"stele\",\"name\":\"Философский пароход\",\"x\":-3764.6,\"z\":-357,\"wikidata\":\"Q1785133\",\"wikipedia\":\"ru:Философский пароход\"},{\"id\":\"n8754362391\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3954.7,\"z\":-305.4,\"inscription\":\"Здесь учились выдающиеся советские флотоводцы: адмигал Головко Арсений Григорьевич с 1925 по 1928 г.г., адмирал Зозуля Федор Владимирович с 1925 по 1928 г.г., адмирал Фокин Виталий Алексеевич с 1924 по 1927 г.г., вице-адмирал Дрозд Валентин Петрович ...\"},{\"id\":\"n8754362392\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3951.3,\"z\":-307.3,\"inscription\":\"Здесь учились выдающиеся мореплаватели: с 1785 по 1788 г.г. Крузенштерн Иван Федорович, с 1783 по 1788 г.г. Лисянский Юрий Федорович, с 1789 по 1797 г.г. Беллинсгаузен Фаддей Фаддеевич, с 1800 по 1808 г.г. Лазарев Михаил Петрович, ...\"},{\"id\":\"n8754362393\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Верещагину\",\"x\":-3985.7,\"z\":-287.6,\"subject\":\"Q127017\",\"inscription\":\"Здесь учился и в 1860 году окончил полный курс Морского кадетского корпуса Василий Васильевич Верещагин, великий русский художник\"},{\"id\":\"n8789928134\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. Эйлеру\",\"x\":-3883.4,\"z\":-347.2,\"subject\":\"Q7604\",\"inscription\":\"Здесь жил с 1766 по 1783 г. Леонард Эйлер, член Петербургской Академии Наук, крупнейший математик, механик и физик\"},{\"id\":\"n7683216135\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. И. Мещанинову\",\"x\":-3675.5,\"z\":-438.6,\"subject\":\"Q1342113\",\"inscription\":\"В этом доме с 1941 по 1967 год жил выдающийся советский языковед и археолог, академик Иван Иванович Мещанинов, 1883–1967\"},{\"id\":\"n7683216136\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. П. Алексееву\",\"x\":-3681.5,\"z\":-435.3,\"subject\":\"Q4061691\",\"inscription\":\"Здесь с 1966 по 1981 год жил и работал советский ученый-филолог, академик Михаил Павлович Алексеев\"},{\"id\":\"n7683216137\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. В. Остроградскому\",\"x\":-3684.2,\"z\":-433.7,\"subject\":\"Q355892\",\"inscription\":\"Здесь жил академик Михаил Васильевич Остроградский, 1801–1861, знаменитый математик. Широко известны его работы по основаниям механики и его формулы в теории кратных интергалов.\"},{\"id\":\"n7685081678\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. Л. Чебышёву\",\"x\":-3684.4,\"z\":-434,\"subject\":\"Q206012\",\"inscription\":\"Здесь жил академик Пафнутий Львович Чебышев, 1821–1894, знаменитый математик, основатель русской школы теории чисел, теории вероятностей, теории механизмов и теории функций, сделавший основные открытия в этих науках.\"},{\"id\":\"n7685081679\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. В. Ферсману\",\"x\":-3681.6,\"z\":-435.6,\"subject\":\"Q365645\",\"inscription\":\"Здесь с 1920 г. по 1936 г. жил академик Александр Евгеньевич Ферсман, выдающийся геохимик и минералог.\"},{\"id\":\"n7685081680\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Палладину\",\"x\":-3675.7,\"z\":-439,\"subject\":\"Q899297\",\"inscription\":\"Здесь жил с 1921 года и 3 февраля 1922 года умер академик Владимир Иванович Палладин, выдающийся русский физиолог растений.\"},{\"id\":\"n13243541964\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-3746.1,\"z\":-410.2},{\"id\":\"n8807401526\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4170.1,\"z\":-431.8,\"inscription\":\"В этом здании с 1921 по 1928 июня 1917 г. работала III Всероссийская конференция профсоюзов. В. И. Ленин руководил деятельностью большевистской фракции и несколько раз выступал на ее заседаниях.\"},{\"id\":\"n8825771659\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. Г. Бубнову\",\"x\":-4478,\"z\":-308.9,\"subject\":\"Q2627249\",\"inscription\":\"В этом доме с 1895 по 1919 жил ученый кораблестроитель Иван Григорьевич Бубнов\"},{\"id\":\"n2535435047\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"В. И. Ленин\",\"x\":-4437.2,\"z\":-416.5,\"subject\":\"Q1394\"},{\"id\":\"n6419485179\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. И. Смородину\",\"x\":-4497.5,\"z\":-409.3,\"subject\":\"Q4425184\",\"inscription\":\"В этом доме с 1929 по 1933 год жил один из организаторов комсомола, Первый секретарь ЦК РКСМ в 1921-1924 годах, видный партийный деятель Пётр Иванович Смородин\"},{\"id\":\"n8807396239\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-4186,\"z\":-403,\"inscription\":\"В этом здании в 1940–1942 годах размещалась 2-я ленинградская военно-морская специальная школа. Воспитанникишколы проявили мужество и стойкость в годы войны и внесли большой вклад в развитие отечественного ВМФ в послевоенный период.\"},{\"id\":\"n8815235640\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Н. Серову\",\"x\":-4335.6,\"z\":-334.6,\"subject\":\"Q442978\",\"inscription\":\"Композитор Александр Николаевич Серов род. в С.П.Б. 11 января 1820 г., умер в этом доме 20 января 1871 г. От Музыкально-исторического о-ва имени графа А. Д. Шереметева\"}]");
